// The tables generated by gerar_fontes.py (fontes_suaves.cpp). The user is
// tab5_ui.cpp - the rest of the system only sees tab5_texto()/tab5_fonte_corpo().
#pragma once
#include <stdint.h>

typedef struct {
  int            altura;   // line height in px (its d.fontHeight())
  const uint8_t* dados;    // the whole VLW file, in flash
  uint32_t       tamanho;
} fonte_suave_t;

extern const fonte_suave_t FONTES_CORPO[];
extern const int           FONTES_CORPO_N;
extern const fonte_suave_t FONTES_NEGRITO[];
extern const int           FONTES_NEGRITO_N;
